package com.cowave.search.auth.controller

import com.cowave.search.auth.dto.AuthUserResponse
import com.cowave.search.auth.service.AuthService
import com.cowave.search.common.security.SsoUserExtractor
import org.springframework.http.ResponseEntity
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RestController

@RestController
@RequestMapping("/auth")
class AuthController(
    private val authService: AuthService,
    private val ssoUserExtractor: SsoUserExtractor,
) {
    /**
     * 현재 SSO 로그인 사용자 정보 반환.
     * SSO 토큰의 email 클레임으로 로컬 User를 조회하여 권한 정보를 포함한 응답 반환.
     */
    @GetMapping
    fun getCurrentUser(): ResponseEntity<AuthUserResponse> {
        val email =
            ssoUserExtractor.currentEmail()
                ?: return ResponseEntity.status(401).build()
        val authUser = authService.getCurrentUser(email)
        return ResponseEntity.ok(authUser)
    }
}

package com.cowave.search.auth.service

import com.cowave.search.auth.dto.AuthUserResponse
import com.cowave.search.auth.infrastructure.UserRepository
import com.cowave.search.auth.infrastructure.UserRoleRepository
import com.cowave.search.common.exception.NotFoundUserException
import org.springframework.stereotype.Service

@Service
class AuthService(
    private val userRepository: UserRepository,
    private val userRoleRepository: UserRoleRepository,
) {
    /**
     * SSO 토큰의 email 클레임으로 로컬 사용자 및 권한 조회.
     * SSO 사용자가 처음 접근하는 경우 User가 없을 수 있으므로 필요 시 자동 생성 로직 추가 가능.
     */
    fun getCurrentUser(email: String): AuthUserResponse {
        val user =
            userRepository
                .findByEmail(email)
                .orElseThrow { NotFoundUserException("존재하지 않는 사용자입니다: $email") }

        val roleId = userRoleRepository.findByUserId(user.id)?.roleId

        return AuthUserResponse(
            id = user.id,
            username = user.username,
            email = user.email,
            roleId = roleId,
        )
    }
}

package com.cowave.search.auth.service

import com.cowave.search.auth.dto.AddUserRequest
import com.cowave.search.auth.dto.EditProfileRequest
import com.cowave.search.auth.dto.UserResponse
import com.cowave.search.auth.infrastructure.UserRepository
import com.cowave.search.auth.infrastructure.UserRoleRepository
import com.cowave.search.auth.model.User
import com.cowave.search.auth.model.UserRole
import com.cowave.search.common.exception.DuplicatedUserException
import com.cowave.search.common.exception.NotFoundUserException
import org.springframework.stereotype.Service
import java.time.LocalDateTime

@Service
class UserService(
    private val userRepository: UserRepository,
    private val userRoleRepository: UserRoleRepository,
) {
    fun findAll(): List<UserResponse> {
        val users = userRepository.findAll()
        val userRoles = userRoleRepository.findAll().associateBy { it.userId }
        return users.map { user ->
            UserResponse.from(user, userRoles[user.id]?.roleId)
        }
    }

    fun findById(id: String): UserResponse {
        val user =
            userRepository
                .findById(id)
                .orElseThrow { NotFoundUserException("존재하지 않는 사용자입니다: $id") }
        val roleId = userRoleRepository.findByUserId(id)?.roleId
        return UserResponse.from(user, roleId)
    }

    /**
     * SSO 사용자 등록 — SSO에서 받은 이메일/이름으로 로컬 권한 매핑 레코드 생성.
     * 비밀번호는 SSO에서 관리하므로 저장하지 않음.
     */
    fun create(request: AddUserRequest): UserResponse {
        if (userRepository.existsByEmail(request.email)) {
            throw DuplicatedUserException("이미 사용 중인 이메일입니다: ${request.email}")
        }

        val user =
            userRepository.save(
                User(
                    username = request.username,
                    email = request.email,
                ),
            )

        request.roleId?.let {
            userRoleRepository.save(UserRole(userId = user.id, roleId = it))
        }

        return UserResponse.from(user, request.roleId)
    }

    fun delete(id: String) {
        userRepository
            .findById(id)
            .orElseThrow { NotFoundUserException("존재하지 않는 사용자입니다: $id") }

        userRoleRepository.deleteByUserId(id)
        userRepository.deleteById(id)
    }

    fun editProfile(
        id: String,
        request: EditProfileRequest,
    ): UserResponse {
        val user =
            userRepository
                .findById(id)
                .orElseThrow { NotFoundUserException("존재하지 않는 사용자입니다: $id") }

        if (user.email != request.email && userRepository.existsByEmail(request.email)) {
            throw DuplicatedUserException("이미 사용 중인 이메일입니다: ${request.email}")
        }

        user.username = request.username
        user.email = request.email
        user.updateDate = LocalDateTime.now()
        userRepository.save(user)

        userRoleRepository.deleteByUserId(id)
        request.roleId?.let {
            userRoleRepository.save(UserRole(userId = id, roleId = it))
        }

        return UserResponse.from(user, request.roleId)
    }
}

package com.cowave.search

import com.cowave.search.common.security.SsoProperties
import com.cowave.search.notice.TelegramProperties
import org.springframework.boot.autoconfigure.SpringBootApplication
import org.springframework.boot.context.properties.EnableConfigurationProperties
import org.springframework.boot.runApplication
import org.springframework.scheduling.annotation.EnableAsync
import org.springframework.scheduling.annotation.EnableScheduling

@SpringBootApplication
@EnableAsync
@EnableScheduling
@EnableConfigurationProperties(SsoProperties::class, TelegramProperties::class)
class SearchAdminServerApplication

fun main(args: Array<String>) {
    runApplication<SearchAdminServerApplication>(*args)
}

