import com.cowave.search.auth.service.UserService
import com.cowave.search.common.exception.ParameterInvalidException
import org.springframework.http.ResponseEntity
import org.springframework.web.bind.annotation.DeleteMapping
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.PathVariable
import org.springframework.web.bind.annotation.PostMapping
import org.springframework.web.bind.annotation.PutMapping
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RequestParam
import org.springframework.web.bind.annotation.RestController

@RestController
@RequestMapping("/users")
class UserController(
    private val userService: UserService,
) {
    @GetMapping
    fun findAll(): ResponseEntity<List<UserResponse>> = ResponseEntity.ok(userService.findAll())

    @GetMapping("/{id}")
    fun findById(
        @PathVariable id: String,
    ): ResponseEntity<UserResponse> = ResponseEntity.ok(userService.findById(id))

    @PostMapping
    fun create(
        @RequestBody request: AddUserRequest,
    ): ResponseEntity<UserResponse> = ResponseEntity.ok(userService.create(request))

    @DeleteMapping("/{id}")
    fun delete(
        @PathVariable id: String,
    ): ResponseEntity<Void> {
        userService.delete(id)
        return ResponseEntity.ok().build()
    }

    @PutMapping("/{id}")
    fun update(
        @PathVariable id: String,
        @RequestParam action: String,
        @RequestBody(required = false) body: Map<String, String>?,
    ): ResponseEntity<UserResponse> {
        val response =
            when (action) {
                "EDIT_PROFILE" -> {
                    val username = body?.get("username") ?: throw ParameterInvalidException("username 필드가 필요합니다.")
                    val email = body["email"] ?: throw ParameterInvalidException("email 필드가 필요합니다.")
                    val roleId = body["roleId"]
                    userService.editProfile(id, EditProfileRequest(username, email, roleId))
                }
                else -> throw ParameterInvalidException("지원하지 않는 action입니다: $action")
            }
        return ResponseEntity.ok(response)
    }
}

